query loadFooterFontent($providers: [String], $path: String) {
  pageOrGame(path: $path, released: true) {
    page {
      pageFooterOverride
    }
  }
  globalContent {
    welcomeBonusTermsAndConditionsShort
    globalFooter
  }
  providers(providers: $providers) {
    image
    legalLine
    title
  }
}

query loadNavigationContent {
  globalContent {
    menuItems {
      link
      text
    }
  }
}

query loadGame( $gameIds: [String], $categoryId: String, $limit: Int, $published: Boolean, $released: Boolean, $sort: String, $tags:[String] ) {
  games(gameIds: $gameIds, categoryId: $categoryId, published: $published, released: $released, limit: $limit, sort: $sort, tags: $tags) {
    id
    categoryId
    order
    title
    titleOverride
    imageSlug
    providerId
    added
    backgroundColour
    link
    video    
    jackpot {
     id
     amount
    }
    labelText
  }
}

